-- Migration 123: Global timezone fix via timezone polygon lookup
-- Source: timezonefinder (uses timezone-boundary-builder data, version 2026c)
-- Method: coordinate → polygon → canonical IANA timezone
-- Cities affected: 2,983 of 152,970 (2%)
--
-- Per spec section 1: "A city timezone must be assigned from the city's
-- latitude and longitude using a trusted geographic timezone-boundary
-- dataset. Country, state, province, county, UTC offset, or timezone
-- abbreviation must not be used as the sole source of truth."
--
-- This migration applies the polygon lookup globally. Previously, only
-- US cities (16,731) had polygon-based timezones (migration 119).
--
-- Excluded from this migration (handled by 124-125):
--   - 22 Null Island (0,0) cities (bad data, needs review)
--   - 13 oceanic/missing-TZ cities (manual overrides in migration 125)
--
-- Top 10 fix patterns:
--    251  Asia/Ho_Chi_Minh                    → Asia/Bangkok
--    223  America/Recife                      → America/Fortaleza
--    218  America/Belem                       → America/Fortaleza
--    178  America/Argentina/Buenos_Aires      → America/Argentina/Cordoba
--    160  America/Mexico_City                 → America/Monterrey
--    126  America/Sao_Paulo                   → America/Araguaina
--    122  Asia/Shanghai                       → Asia/Urumqi
--    111  Europe/Moscow                       → Asia/Yekaterinburg
--    107  Asia/Jakarta                        → Asia/Makassar
--     81  America/Merida                      → America/Mexico_City

-- Idempotent: only updates cities where timezone != new value.

-- Africa/Abidjan (4 cities)
UPDATE cities SET timezone = CASE id WHEN 149092 THEN 'Africa/Abidjan' WHEN 149093 THEN 'Africa/Abidjan' WHEN 149096 THEN 'Africa/Abidjan' WHEN 149117 THEN 'Africa/Abidjan' ELSE timezone END WHERE id IN (149092,149093,149096,149117);

